add('fr', {"cls.eyebrow": "Les classes", "cls.h2": "Choisis ta voie", "cls.p": "Douze classes, douze façons de jouer. Avec le mode héros, emmène-en plusieurs à la fois.", "cls.role.1": "Protecteur", "cls.desc.1": "Gardien aux armures élémentaires et aux glyphes, le Féca protège ses alliés et encaisse les coups.", "cls.role.2": "Invocateur", "cls.desc.2": "L’Osamodas appelle des créatures sauvages et soigne ou renforce ses invocations.", "cls.role.3": "Chasseur de trésors", "cls.desc.3": "L’Enutrof ralentit ses ennemis, augmente la prospection et fait pleuvoir les pièces.", "cls.role.4": "Assassin", "cls.desc.4": "Invisible et sournois, le Sram pose des pièges et frappe là où on ne l’attend pas.", "cls.role.5": "Maître du temps", "cls.desc.5": "Le Xélor vole les PA de ses adversaires, les téléporte et retarde leurs tours.", "cls.role.6": "Joueur", "cls.desc.6": "L’Ecaflip parie sur la chance : coups critiques, roulette et griffes imprévisibles.", "cls.role.7": "Soigneur", "cls.desc.7": "L’Eniripsa soigne et stimule ses alliés par la puissance des mots.", "cls.role.8": "Guerrier", "cls.desc.8": "Le Iop fonce dans la mêlée avec son épée : dégâts massifs et bonds spectaculaires.", "cls.role.9": "Archer", "cls.desc.9": "Le Crâ tire de loin avec une précision redoutable et tient l’ennemi à distance.", "cls.role.10": "Druide", "cls.desc.10": "Le Sadida invoque poupées et ronces et empoisonne ses ennemis avec la nature.", "cls.role.11": "Berserker", "cls.desc.11": "Plus il souffre, plus le Sacrieur frappe fort : il échange sa place et attire ses cibles.", "cls.role.12": "Bagarreur", "cls.desc.12": "Le Pandawa porte, lance et protège ses alliés, et devient plus fort quand il est ivre."});
add('en', {"cls.eyebrow": "Classes", "cls.h2": "Choose your path", "cls.p": "Twelve classes, twelve ways to play. With hero mode, take several of them at once.", "cls.role.1": "Protector", "cls.desc.1": "A guardian with elemental armours and glyphs, the Feca shields allies and takes the hits.", "cls.role.2": "Summoner", "cls.desc.2": "The Osamodas calls wild creatures and heals or empowers its summons.", "cls.role.3": "Treasure hunter", "cls.desc.3": "The Enutrof slows enemies, boosts prospecting and makes coins rain.", "cls.role.4": "Assassin", "cls.desc.4": "Invisible and sneaky, the Sram sets traps and strikes where nobody expects it.", "cls.role.5": "Time master", "cls.desc.5": "The Xelor steals AP from opponents, teleports them and delays their turns.", "cls.role.6": "Gambler", "cls.desc.6": "The Ecaflip bets on luck: critical hits, roulette and unpredictable claws.", "cls.role.7": "Healer", "cls.desc.7": "The Eniripsa heals and stimulates allies with the power of words.", "cls.role.8": "Warrior", "cls.desc.8": "The Iop charges into melee with a sword: massive damage and spectacular leaps.", "cls.role.9": "Archer", "cls.desc.9": "The Cra shoots from afar with deadly precision and keeps enemies at bay.", "cls.role.10": "Druid", "cls.desc.10": "The Sadida summons dolls and brambles and poisons enemies with nature.", "cls.role.11": "Berserker", "cls.desc.11": "The more it suffers, the harder the Sacrier hits; it swaps places with and pulls its targets.", "cls.role.12": "Brawler", "cls.desc.12": "The Pandawa carries, throws and protects allies, and grows stronger when drunk."});
